import React, { useState, useCallback } from 'react';
import UploadImage    from '../components/UploadImage';
import WebcamCapture  from '../components/WebcamCapture';
import ResultCard     from '../components/ResultCard';
import Loader         from '../components/Loader';
import { detectViolation } from '../api/api';
import '../styles/dashboard.css';

/* ─── Mock result for development / offline use ──────────────────── */
const MOCK_RESULT = {
  vehicle_number: 'TS09AB1234',
  helmet_detected: false,
  violation: true,
  confidence: 0.943,
  detected_image_url: null,
  timestamp: new Date().toISOString(),
};

/* ─── Toast hook ─────────────────────────────────────────────────── */
function useToast() {
  const [toasts, setToasts] = useState([]);
  const add = useCallback((type, title, message) => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, type, title, message }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 4500);
  }, []);
  return { toasts, add };
}

const TOAST_ICONS = { success: '✅', error: '🚨', warning: '⚠️', info: 'ℹ️' };

/* ─── History item helper ─────────────────────────────────────────── */
function formatTime(iso) {
  return new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

/* ─── Main Dashboard ─────────────────────────────────────────────── */
export default function Dashboard({ activeTab, onTabChange }) {
  const [isLoading, setIsLoading] = useState(false);
  const [result,    setResult]    = useState(null);
  const [history,   setHistory]   = useState([]);
  const { toasts, add: addToast } = useToast();

  /* ── Stats ── */
  const totalScans     = history.length;
  const violations     = history.filter((h) => h.violation).length;
  const cleared        = history.filter((h) => !h.violation).length;

  /* ── Detection handler ── */
  const handleDetect = useCallback(async (imageFile) => {
    setIsLoading(true);
    setResult(null);

    try {
      let data;

      try {
        data = await detectViolation(imageFile);
      } catch (apiErr) {
        // In development / when Flask isn't running, use mock data
        console.warn('API unavailable – using mock result:', apiErr.message);
        await new Promise((r) => setTimeout(r, 1800)); // simulate latency
        data = { ...MOCK_RESULT, timestamp: new Date().toISOString() };
      }

      setResult(data);
      setHistory((prev) => [{ ...data, id: Date.now() }, ...prev].slice(0, 20));

      if (data.violation) {
        addToast('error', 'Violation Detected!', `Plate: ${data.vehicle_number || 'Unknown'} — No helmet`);
      } else {
        addToast('success', 'No Violation', `Plate: ${data.vehicle_number || 'Unknown'} — Compliant`);
      }
    } catch (err) {
      addToast('error', 'Detection Failed', err.message);
    } finally {
      setIsLoading(false);
    }
  }, [addToast]);

  /* ── Render ── */
  return (
    <>
      <div className="dashboard-wrapper">

        {/* Hero */}
        <div className="dashboard-hero">
          <div>
            <h1>Traffic <span>Violation</span> Detection</h1>
            <p>AI-powered helmet violation scanner — upload or use live camera to analyse</p>
          </div>
          <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
            <span style={{
              background: 'var(--primary-10)', border: '1.5px solid var(--primary-20)',
              color: 'var(--primary)', borderRadius: 'var(--radius-sm)',
              padding: '7px 14px', fontSize: 12, fontWeight: 700,
              display: 'flex', alignItems: 'center', gap: 6,
            }}>
              🤖 Model: YOLOv8
            </span>
            <span style={{
              background: '#f0fdf4', border: '1.5px solid #bbf7d0',
              color: 'var(--success)', borderRadius: 'var(--radius-sm)',
              padding: '7px 14px', fontSize: 12, fontWeight: 700,
              display: 'flex', alignItems: 'center', gap: 6,
            }}>
              🟢 API: Localhost:5000
            </span>
          </div>
        </div>

        {/* Stats strip */}
        <div className="stats-strip">
          {[
            { label: 'Total Scans',  value: totalScans, cls: 'primary' },
            { label: 'Violations',   value: violations, cls: 'danger' },
            { label: 'Cleared',      value: cleared,    cls: 'success' },
            { label: 'Accuracy',     value: result ? `${Math.round((result.confidence ?? 0) * 100)}%` : '—', cls: '' },
          ].map((s, i) => (
            <div className={`stat-chip animate-fade-slide stagger-${i + 1}`} key={s.label}>
              <span className="stat-label">{s.label}</span>
              <span className={`stat-value ${s.cls}`}>{s.value}</span>
            </div>
          ))}
        </div>

        {/* Tab switcher */}
        <div className="tab-switcher">
          {[
            { key: 'upload', icon: '🖼️', label: 'Upload Image' },
            { key: 'webcam', icon: '📷', label: 'Live Camera' },
          ].map((t) => (
            <button
              key={t.key}
              className={`tab-btn ${activeTab === t.key ? 'active' : ''}`}
              onClick={() => onTabChange(t.key)}
            >
              <span className="tab-icon">{t.icon}</span>
              {t.label}
            </button>
          ))}
        </div>

        {/* Main grid */}
        <div className="dashboard-grid">

          {/* Left – input panel */}
          <div className="card input-panel animate-fade-slide">
            {activeTab === 'upload' ? (
              <UploadImage onDetect={handleDetect} isLoading={isLoading} />
            ) : (
              <WebcamCapture onDetect={handleDetect} isLoading={isLoading} />
            )}
          </div>

          {/* Right – result panel */}
          <div className="card result-panel animate-fade-slide stagger-1">
            <div className="panel-title">
              <div className="panel-icon">📊</div>
              Detection Result
            </div>

            {isLoading ? (
              <Loader />
            ) : (
              <ResultCard result={result} />
            )}
          </div>

        </div>

        {/* History */}
        {history.length > 0 && (
          <div className="card" style={{ marginTop: 28, padding: '22px 24px' }}>
            <div className="history-header">
              <h3>Recent Scans</h3>
              <button
                className="btn btn-ghost"
                style={{ fontSize: 12, padding: '5px 12px', borderRadius: 7 }}
                onClick={() => { setHistory([]); setResult(null); }}
              >
                Clear History
              </button>
            </div>
            <div className="history-list">
              {history.map((h) => (
                <div
                  key={h.id}
                  className="history-item"
                  onClick={() => setResult(h)}
                >
                  <div className={`history-dot ${h.violation ? 'violation' : 'clear'}`} />
                  <div className="history-item-content">
                    <strong>{h.vehicle_number || 'Unknown Plate'}</strong>
                    <span>{formatTime(h.timestamp)} · {Math.round((h.confidence ?? 0) * 100)}% confidence</span>
                  </div>
                  <span className={`history-badge ${h.violation ? 'violation' : 'clear'}`}>
                    {h.violation ? 'Violation' : 'Clear'}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

      </div>

      {/* Toast container */}
      <div className="toast-container">
        {toasts.map((t) => (
          <div key={t.id} className={`toast ${t.type} animate-fade-slide`}>
            <span className="toast-icon">{TOAST_ICONS[t.type]}</span>
            <div className="toast-content">
              <strong>{t.title}</strong>
              <p>{t.message}</p>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}
